import React, { useState, useEffect } from "react";
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField,
    Button,
    List,
    ListItem,
    ListItemText,
    IconButton,
    Typography,
    Box,
    Paper,
    Chip
} from "@mui/material";
import { ref, get, push, update, remove } from "firebase/database";
import { db } from "./firebaseConfig";
import NoteIcon from '@mui/icons-material/Note';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import CloseIcon from '@mui/icons-material/Close';
import WarningIcon from '@mui/icons-material/Warning';
import InfoIcon from '@mui/icons-material/Info';
import StarIcon from '@mui/icons-material/Star';

const NotasImportantes = ({ alumnoId, alumnoNombre, open, onClose }) => {
    const [notas, setNotas] = useState([]);
    const [notaDialogOpen, setNotaDialogOpen] = useState(false);
    const [notaEditando, setNotaEditando] = useState(null);
    const [nuevaNota, setNuevaNota] = useState({
        titulo: "",
        contenido: "",
        fecha: new Date().toISOString().split('T')[0],
        prioridad: "normal" // normal, importante, urgente
    });
    const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false);
    const [notaAEliminar, setNotaAEliminar] = useState(null);

    // Cargar notas del alumno
    useEffect(() => {
        if (alumnoId) {
            cargarNotas();
        }
    }, [alumnoId]);

    const cargarNotas = async () => {
        try {
            const notasRef = ref(db, `notas/${alumnoId}`);
            const snapshot = await get(notasRef);

            if (snapshot.exists()) {
                const data = snapshot.val();
                const notasList = Object.entries(data).map(([key, value]) => ({
                    id: key,
                    ...value
                }));
                // Ordenar por prioridad y fecha
                notasList.sort((a, b) => {
                    const prioridadOrden = { urgente: 1, importante: 2, normal: 3 };
                    if (prioridadOrden[a.prioridad] !== prioridadOrden[b.prioridad]) {
                        return prioridadOrden[a.prioridad] - prioridadOrden[b.prioridad];
                    }
                    return new Date(b.fecha) - new Date(a.fecha);
                });
                setNotas(notasList);
            } else {
                setNotas([]);
            }
        } catch (error) {
            console.error("Error al cargar notas:", error);
        }
    };

    const abrirDialogoNota = (nota = null) => {
        if (nota) {
            setNotaEditando(nota);
            setNuevaNota({
                titulo: nota.titulo,
                contenido: nota.contenido,
                fecha: nota.fecha,
                prioridad: nota.prioridad
            });
        } else {
            setNotaEditando(null);
            setNuevaNota({
                titulo: "",
                contenido: "",
                fecha: new Date().toISOString().split('T')[0],
                prioridad: "normal"
            });
        }
        setNotaDialogOpen(true);
    };

    const guardarNota = async () => {
        if (!nuevaNota.titulo || !nuevaNota.contenido) {
            alert("Por favor, completa el título y contenido de la nota");
            return;
        }

        try {
            const notasRef = ref(db, `notas/${alumnoId}`);

            if (notaEditando) {
                // Editar nota existente
                await update(ref(db, `notas/${alumnoId}/${notaEditando.id}`), {
                    ...nuevaNota,
                    ultimaModificacion: new Date().toISOString()
                });
            } else {
                // Crear nueva nota
                await push(notasRef, {
                    ...nuevaNota,
                    creada: new Date().toISOString()
                });
            }

            setNotaDialogOpen(false);
            cargarNotas();
        } catch (error) {
            console.error("Error al guardar nota:", error);
            alert("Error al guardar la nota");
        }
    };

    const confirmarEliminarNota = (nota) => {
        setNotaAEliminar(nota);
        setConfirmDeleteOpen(true);
    };

    const eliminarNota = async () => {
        if (!notaAEliminar) return;

        try {
            await remove(ref(db, `notas/${alumnoId}/${notaAEliminar.id}`));
            setConfirmDeleteOpen(false);
            setNotaAEliminar(null);
            cargarNotas();
        } catch (error) {
            console.error("Error al eliminar nota:", error);
            alert("Error al eliminar la nota");
        }
    };

    const getPrioridadColor = (prioridad) => {
        switch (prioridad) {
            case "urgente":
                return { color: "#f44336", icono: <WarningIcon />, texto: "Urgente" };
            case "importante":
                return { color: "#ff9800", icono: <StarIcon />, texto: "Importante" };
            default:
                return { color: "#2196f3", icono: <InfoIcon />, texto: "Normal" };
        }
    };

    return (
        <>
            {/* Dialog principal de notas */}
            <Dialog
                open={open}
                onClose={onClose}
                maxWidth="md"
                fullWidth
                PaperProps={{
                    sx: {
                        borderRadius: 3,
                        backgroundColor: '#1e1e1e',
                        minHeight: '500px'
                    }
                }}
            >
                <DialogTitle sx={{
                    color: 'white',
                    borderBottom: '1px solid rgba(255,255,255,0.1)',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center'
                }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <NoteIcon sx={{ color: '#ffd700' }} />
                        <Typography variant="h6">
                            Notas Importantes - {alumnoNombre}
                        </Typography>
                    </Box>
                    <IconButton onClick={onClose} sx={{ color: 'white' }}>
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>

                <DialogContent sx={{ mt: 2 }}>
                    <Button
                        variant="contained"
                        color="primary"
                        onClick={() => abrirDialogoNota()}
                        sx={{ mb: 2 }}
                    >
                        + Agregar Nota
                    </Button>

                    {notas.length === 0 ? (
                        <Paper sx={{
                            p: 4,
                            textAlign: 'center',
                            backgroundColor: '#2d2d2d',
                            color: 'rgba(255,255,255,0.7)'
                        }}>
                            <NoteIcon sx={{ fontSize: 60, color: 'rgba(255,255,255,0.3)', mb: 2 }} />
                            <Typography variant="h6">
                                No hay notas para este alumno
                            </Typography>
                            <Typography variant="body2">
                                Haz clic en "Agregar Nota" para crear una nueva
                            </Typography>
                        </Paper>
                    ) : (
                        <List>
                            {notas.map((nota) => {
                                const prioridad = getPrioridadColor(nota.prioridad);
                                return (
                                    <Paper
                                        key={nota.id}
                                        sx={{
                                            mb: 2,
                                            backgroundColor: '#2d2d2d',
                                            borderRadius: 2,
                                            overflow: 'hidden'
                                        }}
                                    >
                                        <ListItem
                                            sx={{
                                                flexDirection: 'column',
                                                alignItems: 'stretch'
                                            }}
                                        >
                                            <Box sx={{
                                                display: 'flex',
                                                justifyContent: 'space-between',
                                                alignItems: 'center',
                                                mb: 1,
                                                width: '100%'
                                            }}>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                    <Chip
                                                        icon={prioridad.icono}
                                                        label={prioridad.texto}
                                                        size="small"
                                                        sx={{
                                                            backgroundColor: prioridad.color,
                                                            color: 'white',
                                                            '& .MuiChip-icon': { color: 'white' }
                                                        }}
                                                    />
                                                    <Typography variant="subtitle1" sx={{ color: 'white', fontWeight: 'bold' }}>
                                                        {nota.titulo}
                                                    </Typography>
                                                </Box>
                                                <Box>
                                                    <IconButton
                                                        size="small"
                                                        onClick={() => abrirDialogoNota(nota)}
                                                        sx={{ color: '#4caf50' }}
                                                    >
                                                        <EditIcon />
                                                    </IconButton>
                                                    <IconButton
                                                        size="small"
                                                        onClick={() => confirmarEliminarNota(nota)}
                                                        sx={{ color: '#f44336' }}
                                                    >
                                                        <DeleteIcon />
                                                    </IconButton>
                                                </Box>
                                            </Box>

                                            <Typography
                                                variant="body2"
                                                sx={{
                                                    color: 'rgba(255,255,255,0.9)',
                                                    whiteSpace: 'pre-wrap',
                                                    mb: 1
                                                }}
                                            >
                                                {nota.contenido}
                                            </Typography>

                                            <Typography
                                                variant="caption"
                                                sx={{ color: 'rgba(255,255,255,0.5)' }}
                                            >
                                                Fecha: {new Date(nota.fecha).toLocaleDateString('es-ES')}
                                                {nota.ultimaModificacion && " (modificada)"}
                                            </Typography>
                                        </ListItem>
                                    </Paper>
                                );
                            })}
                        </List>
                    )}
                </DialogContent>
            </Dialog>

            {/* Dialog para agregar/editar nota */}
            <Dialog
                open={notaDialogOpen}
                onClose={() => setNotaDialogOpen(false)}
                maxWidth="sm"
                fullWidth
                PaperProps={{
                    sx: {
                        borderRadius: 3,
                        backgroundColor: '#1e1e1e'
                    }
                }}
            >
                <DialogTitle sx={{ color: 'white' }}>
                    {notaEditando ? 'Editar Nota' : 'Nueva Nota'}
                </DialogTitle>
                <DialogContent>
                    <TextField
                        label="Título"
                        fullWidth
                        value={nuevaNota.titulo}
                        onChange={(e) => setNuevaNota({ ...nuevaNota, titulo: e.target.value })}
                        margin="dense"
                        sx={{
                            '& .MuiInputBase-root': { color: 'white' },
                            '& .MuiInputLabel-root': { color: 'rgba(255, 255, 255, 0.7)' },
                            '& .MuiOutlinedInput-root': {
                                '& fieldset': { borderColor: 'rgba(255, 255, 255, 0.3)' },
                                '&:hover fieldset': { borderColor: 'rgba(255, 255, 255, 0.5)' }
                            }
                        }}
                    />
                    <TextField
                        label="Contenido"
                        fullWidth
                        multiline
                        rows={4}
                        value={nuevaNota.contenido}
                        onChange={(e) => setNuevaNota({ ...nuevaNota, contenido: e.target.value })}
                        margin="dense"
                        sx={{
                            '& .MuiInputBase-root': { color: 'white' },
                            '& .MuiInputLabel-root': { color: 'rgba(255, 255, 255, 0.7)' },
                            '& .MuiOutlinedInput-root': {
                                '& fieldset': { borderColor: 'rgba(255, 255, 255, 0.3)' },
                                '&:hover fieldset': { borderColor: 'rgba(255, 255, 255, 0.5)' }
                            }
                        }}
                    />
                    <TextField
                        label="Fecha"
                        type="date"
                        fullWidth
                        InputLabelProps={{ shrink: true }}
                        value={nuevaNota.fecha}
                        onChange={(e) => setNuevaNota({ ...nuevaNota, fecha: e.target.value })}
                        margin="dense"
                        sx={{
                            '& .MuiInputBase-root': { color: 'white' },
                            '& .MuiInputLabel-root': { color: 'rgba(255, 255, 255, 0.7)' },
                            '& .MuiOutlinedInput-root': {
                                '& fieldset': { borderColor: 'rgba(255, 255, 255, 0.3)' },
                                '&:hover fieldset': { borderColor: 'rgba(255, 255, 255, 0.5)' }
                            }
                        }}
                    />
                    <Box sx={{ mt: 2 }}>
                        <Typography variant="subtitle2" sx={{ color: 'rgba(255,255,255,0.7)', mb: 1 }}>
                            Prioridad:
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1 }}>
                            <Chip
                                label="Normal"
                                onClick={() => setNuevaNota({ ...nuevaNota, prioridad: "normal" })}
                                sx={{
                                    backgroundColor: nuevaNota.prioridad === "normal" ? '#2196f3' : '#2d2d2d',
                                    color: 'white',
                                    cursor: 'pointer',
                                    '&:hover': { backgroundColor: '#2196f3' }
                                }}
                            />
                            <Chip
                                label="Importante"
                                onClick={() => setNuevaNota({ ...nuevaNota, prioridad: "importante" })}
                                sx={{
                                    backgroundColor: nuevaNota.prioridad === "importante" ? '#ff9800' : '#2d2d2d',
                                    color: 'white',
                                    cursor: 'pointer',
                                    '&:hover': { backgroundColor: '#ff9800' }
                                }}
                            />
                            <Chip
                                label="Urgente"
                                onClick={() => setNuevaNota({ ...nuevaNota, prioridad: "urgente" })}
                                sx={{
                                    backgroundColor: nuevaNota.prioridad === "urgente" ? '#f44336' : '#2d2d2d',
                                    color: 'white',
                                    cursor: 'pointer',
                                    '&:hover': { backgroundColor: '#f44336' }
                                }}
                            />
                        </Box>
                    </Box>
                </DialogContent>
                <DialogActions sx={{ backgroundColor: '#1e1e1e' }}>
                    <Button onClick={() => setNotaDialogOpen(false)} sx={{ color: 'white' }}>
                        Cancelar
                    </Button>
                    <Button onClick={guardarNota} color="primary" variant="contained">
                        {notaEditando ? 'Guardar Cambios' : 'Agregar'}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Dialog de confirmación para eliminar nota */}
            <Dialog
                open={confirmDeleteOpen}
                onClose={() => setConfirmDeleteOpen(false)}
                PaperProps={{
                    sx: {
                        borderRadius: 3,
                        backgroundColor: '#1e1e1e'
                    }
                }}
            >
                <DialogTitle sx={{ color: 'white' }}>Confirmar Eliminación</DialogTitle>
                <DialogContent>
                    <Typography sx={{ color: 'white' }}>
                        ¿Estás seguro que deseas eliminar esta nota?
                    </Typography>
                </DialogContent>
                <DialogActions sx={{ backgroundColor: '#1e1e1e' }}>
                    <Button onClick={() => setConfirmDeleteOpen(false)} sx={{ color: 'white' }}>
                        Cancelar
                    </Button>
                    <Button onClick={eliminarNota} color="error" variant="contained">
                        Eliminar
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
};

export default NotasImportantes;