import React, { useState, useEffect } from 'react';
import { Box, Typography, Button, Popover, IconButton, Stack } from '@mui/material';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import CloseIcon from '@mui/icons-material/Close';

const CalendarioAsistencia = ({ alumnoId, diasAsistencia = [], onUpdate }) => {
    const [mesActual, setMesActual] = useState(new Date().getMonth());
    const [anioActual, setAnioActual] = useState(new Date().getFullYear());
    const [anchorEl, setAnchorEl] = useState(null);

    // Función para normalizar fechas a formato YYYY-MM-DD
    const normalizarFecha = (fecha) => {
        if (!fecha) return null;

        if (typeof fecha === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
            return fecha;
        }

        if (fecha instanceof Date) {
            return fecha.toISOString().split('T')[0];
        }

        if (typeof fecha === 'object' && fecha.toDate) {
            return fecha.toDate().toISOString().split('T')[0];
        }

        return null;
    };

    // Obtener fechas del mes actual para mostrar
    const getFechasDelMes = () => {
        return diasAsistencia
            .map(normalizarFecha)
            .filter(f => {
                if (!f) return false;
                const [year, month] = f.split('-').map(Number);
                return year === anioActual && month === mesActual + 1;
            });
    };

    const handleDiaClick = (dia) => {
        const nuevaFecha = new Date(anioActual, mesActual, dia);
        const fechaFormateada = nuevaFecha.toISOString().split('T')[0];

        const nuevosDias = diasAsistencia.includes(fechaFormateada)
            ? diasAsistencia.filter(f => f !== fechaFormateada)
            : [...diasAsistencia, fechaFormateada];

        if (onUpdate) {
            onUpdate(alumnoId, nuevosDias);
        }
    };

    const cambiarMes = (incremento) => {
        const nuevaFecha = new Date(anioActual, mesActual + incremento, 1);
        setMesActual(nuevaFecha.getMonth());
        setAnioActual(nuevaFecha.getFullYear());
    };

    const renderDiasSemana = () => {
        return (
            <Box display="grid" gridTemplateColumns="repeat(7, 1fr)" gap={1} mb={1}>
                {['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'].map(dia => (
                    <Typography key={dia} align="center" variant="caption" color="yellow">
                        {dia}
                    </Typography>
                ))}
            </Box>
        );
    };

    const renderDiasMes = () => {
        const totalDias = new Date(anioActual, mesActual + 1, 0).getDate();
        const primerDia = new Date(anioActual, mesActual, 1).getDay();
        const dias = [];

        for (let i = 0; i < primerDia; i++) {
            dias.push(<Box key={`empty-${i}`} />);
        }

        for (let dia = 1; dia <= totalDias; dia++) {
            const nuevoDia = String(dia).padStart(2, '0');
            const nuevoMes = String(mesActual + 1).padStart(2, '0');
            const fecha = `${anioActual}-${nuevoMes}-${nuevoDia}`;
            const estaMarcado = getFechasDelMes().includes(fecha);

            dias.push(
                <Box
                    key={`dia-${dia}`}
                    onClick={() => handleDiaClick(dia)}
                    sx={{
                        width: 30,
                        height: 30,
                        color:'white',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        borderRadius: '40%',
                        bgcolor: estaMarcado ? 'secondary.main' : 'transparent',
                        color: estaMarcado ? 'white' : 'white',
                        cursor: 'pointer',
                        '&:hover': {
                            bgcolor: estaMarcado ? 'primary.dark' : 'action.hover',
                        },
                    }}
                >
                    {dia}
                </Box>
            );
        }

        return (
            <Box display="grid" gridTemplateColumns="repeat(7, 1fr)" gap={1} >
                {dias}
            </Box>
        );
    };

    const handleOpen = (event) => {
        setAnchorEl(event.currentTarget);
    };

    const handleClose = () => {
        setAnchorEl(null);
    };

    return (
        <>
            <IconButton onClick={handleOpen} color="primary">
                <CalendarTodayIcon />
                <Typography variant="caption" sx={{ ml: 1, color:'orangered' }}>
                    {getFechasDelMes().length}
                </Typography>
            </IconButton>

            <Popover
                open={Boolean(anchorEl)}
                anchorEl={anchorEl}
                onClose={handleClose}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
                transformOrigin={{ vertical: 'top', horizontal: 'center' }}
                sx={{ml:3}}
               
               
            >
                <Box sx={{ p: 2, ml: 2, bgcolor: 'black', borderRadius: 1, minWidth: 300 }}>
                    <Stack direction="row" justifyContent="space-between"  alignItems="center" mb={1}>
                        <Typography variant="subtitle1" color='cyan'>
                            {new Date(anioActual, mesActual).toLocaleDateString('es-ES', {
                                month: 'long',
                                year: 'numeric'
                            })}
                        </Typography>
                        <IconButton
                            size="small"
                            onClick={handleClose}
                            sx={{ marginLeft: 'auto', color:'red' }}
                        >
                            <CloseIcon fontSize="small" />
                        </IconButton>
                    </Stack>

                    <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                        <Button size="small" onClick={() => cambiarMes(-1)}>&lt;</Button>
                        <Button size="small" onClick={() => cambiarMes(1)}>&gt;</Button>
                    </Box>

                    {renderDiasSemana()}
                    {renderDiasMes()}

                   
                </Box>
            </Popover>
        </>
    );
};

export default CalendarioAsistencia;