import React, { useState, useEffect } from "react";
import {
    Box,
    Typography,
    Button,
    TextField,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    IconButton
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import { ref, get, push, set } from "firebase/database";
import { db } from "./firebaseConfig";
import fondo from './fondo.jpg';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';

const VentaVarios = ({ }) => {
    const navigate = useNavigate();
    const [cliente, setCliente] = useState("");
    const [ventas, setVentas] = useState([]);
    const [nuevoProducto, setNuevoProducto] = useState({ nombre: "", precio: "", cantidad: "" });
    const [productosSeleccionados, setProductosSeleccionados] = useState([]);
    const [openDialog, setOpenDialog] = useState(false);
    const [totalGananciasAlumnos, setTotalGananciasAlumnos] = useState(0);
    const [historialGanancias, setHistorialGanancias] = useState([]);
    const [showHistorial, setShowHistorial] = useState(false);
    const [pagosAlumnos, setPagosAlumnos] = useState([]);

    useEffect(() => {
        const cargarDatos = async () => {
            await Promise.all([
                cargarVentasDelMes(),
                cargarGananciasAlumnos(),
                cargarHistorialGanancias()
            ]);
        };
        cargarDatos();
    }, []);

    const cargarVentasDelMes = async () => {
        try {
            const ventasRef = ref(db, "ventas");
            const snapshot = await get(ventasRef);
            if (snapshot.exists()) {
                const data = snapshot.val();
                const mesActual = new Date().getMonth() + 1;
                const anioActual = new Date().getFullYear();

                const ventasFiltradas = Object.values(data).filter(
                    (venta) => {
                        const fechaVenta = new Date(venta.fecha);
                        return fechaVenta.getMonth() + 1 === mesActual &&
                            fechaVenta.getFullYear() === anioActual;
                    }
                );
                setVentas(ventasFiltradas);
            }
        } catch (error) {
            console.error("Error al cargar las ventas:", error);
        }
    };

    const cargarGananciasAlumnos = async () => {
        try {
            const pagosRef = ref(db, "pagos");
            const alumnosRef = ref(db, "alumnos");

            const [pagosSnapshot, alumnosSnapshot] = await Promise.all([
                get(pagosRef),
                get(alumnosRef)
            ]);

            if (!pagosSnapshot.exists()) {
                console.log("No hay datos de pagos en la base de datos");
                setPagosAlumnos([]);
                setTotalGananciasAlumnos(0);
                return;
            }

            const pagosData = pagosSnapshot.val();
            const alumnosData = alumnosSnapshot.exists() ? alumnosSnapshot.val() : {};
            const mesActual = new Date().getMonth() + 1;
            const anioActual = new Date().getFullYear();

            let total = 0;
            let pagosMesActual = [];

            // Recorremos todos los alumnos que tienen pagos
            Object.entries(pagosData).forEach(([alumnoId, pagos]) => {
                // Obtenemos el nombre del alumno
                const alumno = alumnosData[alumnoId] || {};
                const nombreAlumno = alumno.nombre
                    ? `${alumno.nombre} ${alumno.apellido || ''}`.trim()
                    : `Alumno ${alumnoId}`;

                // Verificamos que pagos sea un objeto válido
                if (pagos && typeof pagos === 'object') {
                    Object.entries(pagos).forEach(([pagoId, pago]) => {
                        try {
                            // Validamos que el pago tenga los campos necesarios
                            if (pago && pago.monto && pago.fechaPago) {
                                // Parseamos la fecha (maneja diferentes formatos)
                                let fechaPago;
                                if (typeof pago.fechaPago === 'string') {
                                    // Intenta parsear como ISO (YYYY-MM-DD)
                                    if (pago.fechaPago.includes('T')) {
                                        fechaPago = new Date(pago.fechaPago);
                                    } else {
                                        // Asume formato YYYY-MM-DD sin hora
                                        fechaPago = new Date(pago.fechaPago + 'T00:00:00');
                                    }
                                } else if (pago.fechaPago instanceof Date) {
                                    fechaPago = pago.fechaPago;
                                } else {
                                    console.error('Formato de fecha no reconocido:', pago.fechaPago);
                                    return;
                                }

                                // Verificamos si la fecha es válida
                                if (isNaN(fechaPago.getTime())) {
                                    console.error('Fecha inválida:', pago.fechaPago);
                                    return;
                                }

                                // Verificamos si el pago es del mes actual
                                if (fechaPago.getMonth() + 1 === mesActual &&
                                    fechaPago.getFullYear() === anioActual) {

                                    total += Number(pago.monto);
                                    pagosMesActual.push({
                                        id: pagoId,
                                        alumnoId,
                                        alumno: nombreAlumno,
                                        monto: Number(pago.monto),
                                        fecha: pago.fechaPago,
                                        fechaObj: fechaPago,
                                        descripcion: pago.descripcion || "Pago de clases"
                                    });
                                }
                            }
                        } catch (error) {
                            console.error(`Error procesando pago ${pagoId} del alumno ${alumnoId}:`, error);
                        }
                    });
                }
            });

            // Ordenamos los pagos por fecha (más reciente primero)
            pagosMesActual.sort((a, b) => b.fechaObj - a.fechaObj);

            setTotalGananciasAlumnos(total);
            setPagosAlumnos(pagosMesActual);

            console.log('Pagos cargados:', pagosMesActual);
            console.log('Total ganancias alumnos:', total);

        } catch (error) {
            console.error("Error al cargar las ganancias de alumnos:", error);
            // Muestra un mensaje al usuario si es necesario
        }
    };

    const cargarHistorialGanancias = async () => {
        try {
            const [ventasSnapshot, pagosSnapshot, alumnosSnapshot] = await Promise.all([
                get(ref(db, "ventas")),
                get(ref(db, "pagos")),
                get(ref(db, "alumnos"))
            ]);

            const historial = {};
            const alumnosData = alumnosSnapshot.exists() ? alumnosSnapshot.val() : {};

            // Procesar ventas (igual que antes)
            if (ventasSnapshot.exists()) {
                Object.values(ventasSnapshot.val()).forEach(venta => {
                    const fecha = new Date(venta.fecha);
                    const mes = fecha.getMonth() + 1;
                    const anio = fecha.getFullYear();
                    const key = `${anio}-${mes}`;

                    if (!historial[key]) {
                        historial[key] = {
                            mes,
                            anio,
                            totalVentas: 0,
                            totalClases: 0,
                            detallesClases: []
                        };
                    }
                    historial[key].totalVentas += venta.total;
                });
            }

            // Procesar pagos de alumnos (modificado para incluir nombres)
            if (pagosSnapshot.exists()) {
                Object.entries(pagosSnapshot.val()).forEach(([alumnoId, pagosAlumno]) => {
                    const alumno = alumnosData[alumnoId] || {};
                    const nombreAlumno = alumno.nombre
                        ? `${alumno.nombre} ${alumno.apellido || ''}`.trim()
                        : `Alumno ${alumnoId}`;

                    Object.entries(pagosAlumno).forEach(([pagoId, pago]) => {
                        if (typeof pago === 'object' && pago.monto) {
                            const fecha = new Date(pago.fechaPago);
                            const mes = fecha.getMonth() + 1;
                            const anio = fecha.getFullYear();
                            const key = `${anio}-${mes}`;

                            if (!historial[key]) {
                                historial[key] = {
                                    mes,
                                    anio,
                                    totalVentas: 0,
                                    totalClases: 0,
                                    detallesClases: []
                                };
                            }

                            historial[key].totalClases += pago.monto;
                            historial[key].detallesClases.push({
                                alumno: nombreAlumno, // Usamos el nombre completo aquí
                                monto: pago.monto,
                                fecha: pago.fechaPago,
                                descripcion: pago.descripcion || "Pago de clases"
                            });
                        }
                    });
                });
            }

            // Ordenar historial
            const historialArray = Object.values(historial).sort((a, b) => {
                if (a.anio !== b.anio) return b.anio - a.anio;
                return b.mes - a.mes;
            });

            setHistorialGanancias(historialArray);
        } catch (error) {
            console.error("Error al cargar el historial de ganancias:", error);
        }
    };

    const handleAgregarProducto = () => {
        if (!nuevoProducto.nombre || !nuevoProducto.precio || !nuevoProducto.cantidad) {
            alert("Ingresa nombre, precio y cantidad del producto.");
            return;
        }
        setProductosSeleccionados((prev) => [...prev, { ...nuevoProducto }]);
        setNuevoProducto({ nombre: "", precio: "", cantidad: "" });
        setOpenDialog(false);
    };

    const handleVentaSubmit = async () => {
        if (!cliente.trim()) {
            alert("Ingresa el nombre del cliente.");
            return;
        }
        if (productosSeleccionados.length === 0) {
            alert("Agrega al menos un producto a la venta.");
            return;
        }
        const totalVenta = productosSeleccionados.reduce(
            (total, producto) => total + (parseFloat(producto.precio) * parseInt(producto.cantidad)),
            0
        );

        try {
            const ventasRef = ref(db, "ventas");
            const nuevaVenta = push(ventasRef);
            await set(nuevaVenta, {
                cliente,
                productos: productosSeleccionados,
                fecha: new Date().toISOString(),
                descripcion: `Venta a ${cliente} con ${productosSeleccionados.length} productos. Total: $${totalVenta}`,
                total: totalVenta
            });
            setCliente("");
            setProductosSeleccionados([]);
            cargarVentasDelMes();
            cargarHistorialGanancias();
        } catch (error) {
            console.error("Error al registrar la venta:", error);
        }
    };

    const totalVentasMes = ventas.reduce((total, venta) => total + venta.total, 0);

    const obtenerNombreMes = (mes) => {
        const meses = [
            "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
            "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
        ];
        return meses[mes - 1] || mes;
    };

    return (
        <Box sx={{
            padding: 3,
            backgroundColor: "#121212",
            borderRadius: 2,
            boxShadow: 2,
            color: "#ffffff",
            minHeight: "100vh"
        }}>
            <Box sx={{
                display: 'flex',
                justifyContent: 'center',
                mb: 2
            }}>
                <Typography
                    variant="h3"
                    component="h2"
                    textAlign={'center'}
                    sx={{
                        mt: 4,
                        mb: 4,
                        fontWeight: 'bold',
                        color: '#bb86fc',
                        textShadow: "0 0 10px rgba(187, 134, 252, 0.5)"
                    }}
                >
                    Huma Brc
                </Typography>
            </Box>

            <Typography variant="h4" textAlign="center" gutterBottom sx={{ color: "#03dac6" }}>Venta de Productos</Typography>

            <Box sx={{ display: 'flex', justifyContent: 'center', pb: 1 }}>
                <TextField
                    color="secondary"
                    sx={{
                        display: 'flex',
                        justifyContent: 'center',
                        width: '50%',
                        '& .MuiInputLabel-root': { color: '#bb86fc' },
                        '& .MuiOutlinedInput-root': {
                            '& fieldset': { borderColor: '#bb86fc' },
                            '&:hover fieldset': { borderColor: '#bb86fc' },
                            '&.Mui-focused fieldset': { borderColor: '#bb86fc' }
                        },
                        '& .MuiInputBase-input': { color: '#ffffff' }
                    }}
                    label="Nombre del Cliente"
                    value={cliente}
                    onChange={(e) => setCliente(e.target.value)}
                    margin="normal"
                />
            </Box>

            <Typography textAlign='center' variant="h6" sx={{ mt: 3, color: "#bb86fc" }}>Productos Seleccionados:</Typography>
            <ul style={{ color: "#ffffff" }}>
                {productosSeleccionados.map((producto, index) => (
                    <li key={index} style={{ color: "#ffffff" }}>
                        <span style={{ color: "#03dac6" }}>{producto.nombre}</span> -
                        <span style={{ color: "#ff7597" }}> ${producto.precio}</span> x
                        <span style={{ color: "#03dac6" }}> {producto.cantidad}</span>
                    </li>
                ))}
            </ul>

            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
                <Button
                    variant="contained"
                    color="secondary"
                    sx={{
                        borderRadius: 7,
                        backgroundColor: "#bb86fc",
                        '&:hover': { backgroundColor: "#9a67ea" }
                    }}
                    onClick={() => setOpenDialog(true)}
                >
                    Agregar Producto
                </Button>
            </Box>

            <Dialog
                open={openDialog}
                onClose={() => setOpenDialog(false)}
                PaperProps={{
                    style: {
                        backgroundColor: "#1e1e1e",
                        color: "#ffffff"
                    }
                }}
            >
                <DialogTitle style={{ color: "#bb86fc" }}>Agregar Producto</DialogTitle>
                <DialogContent>
                    <TextField
                        label="Nombre"
                        fullWidth
                        value={nuevoProducto.nombre}
                        onChange={(e) => setNuevoProducto({ ...nuevoProducto, nombre: e.target.value })}
                        margin="normal"
                        InputLabelProps={{ style: { color: "#bb86fc" } }}
                        InputProps={{ style: { color: "#ffffff" } }}
                    />
                    <TextField
                        label="Precio"
                        fullWidth
                        type="number"
                        value={nuevoProducto.precio}
                        onChange={(e) => setNuevoProducto({ ...nuevoProducto, precio: e.target.value })}
                        margin="normal"
                        InputLabelProps={{ style: { color: "#bb86fc" } }}
                        InputProps={{ style: { color: "#ffffff" } }}
                    />
                    <TextField
                        label="Cantidad"
                        fullWidth
                        type="number"
                        value={nuevoProducto.cantidad}
                        onChange={(e) => setNuevoProducto({ ...nuevoProducto, cantidad: e.target.value })}
                        margin="normal"
                        InputLabelProps={{ style: { color: "#bb86fc" } }}
                        InputProps={{ style: { color: "#ffffff" } }}
                    />
                </DialogContent>
                <DialogActions>
                    <Button
                        onClick={() => setOpenDialog(false)}
                        style={{ color: "#ff7597" }}
                    >
                        Cancelar
                    </Button>
                    <Button
                        onClick={handleAgregarProducto}
                        style={{ color: "#03dac6" }}
                    >
                        Agregar
                    </Button>
                </DialogActions>
            </Dialog>

            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
                <Button
                    variant="contained"
                    sx={{
                        ml: 2,
                        borderRadius: 7,
                        backgroundColor: "#03dac6",
                        '&:hover': { backgroundColor: "#018786" }
                    }}
                    onClick={handleVentaSubmit}
                >
                    Confirmar Venta
                </Button>
            </Box>

            <Typography textAlign='center' variant="h5" sx={{ mt: 4, color: "#bb86fc" }}>Ventas del Mes</Typography>
            {ventas.length === 0 ? (
                <Typography textAlign='center' sx={{ mt: 2, color: "#ff7597" }}>Todavía no hay Ventas.</Typography>
            ) : (
                ventas.map((venta, index) => (
                    <Box
                        key={index}
                        sx={{
                            p: 2,
                            mt: 2,
                            border: "1px solid #bb86fc",
                            borderRadius: 2,
                            backgroundColor: "#1e1e1e"
                        }}
                    >
                        <Typography style={{ color: "#ffffff" }}>{venta.descripcion} - Total: <span style={{ color: "#03dac6" }}>${venta.total}</span></Typography>
                        <ul style={{ color: "#ffffff" }}>
                            {venta.productos.map((producto, idx) => (
                                <li key={idx}>
                                    <span style={{ color: "#03dac6" }}>{producto.nombre}</span> -
                                    <span style={{ color: "#ff7597" }}> ${producto.precio}</span> x
                                    <span style={{ color: "#03dac6" }}> {producto.cantidad}</span>
                                </li>
                            ))}
                        </ul>
                    </Box>
                ))
            )}

            <Typography textAlign='center' variant="h5" sx={{ mt: 4, color: "#bb86fc" }}>Pagos de Alumnos del Mes</Typography>
            {pagosAlumnos.length === 0 ? (
                <Typography textAlign='center' sx={{ mt: 2, color: "#ff7597" }}>
                    No se encontraron pagos de alumnos este mes.
                </Typography>
            ) : (
                <TableContainer
                    component={Paper}
                    sx={{
                        mt: 2,
                        mb: 4,
                        backgroundColor: "#1e1e1e"
                    }}
                >
                    <Table>
                        <TableHead>
                            <TableRow sx={{ backgroundColor: '#3700b3' }}>
                                <TableCell sx={{ fontWeight: 'bold', color: "#ffffff" }}>Alumno</TableCell>
                                <TableCell align="right" sx={{ fontWeight: 'bold', color: "#ffffff" }}>Monto ($)</TableCell>
                                <TableCell sx={{ fontWeight: 'bold', color: "#ffffff" }}>Fecha</TableCell>
                                <TableCell sx={{ fontWeight: 'bold', color: "#ffffff" }}>Descripción</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {pagosAlumnos.map((pago) => {
                                // Formatear la fecha para mostrar
                                let fechaFormateada;
                                try {
                                    fechaFormateada = new Date(pago.fecha).toLocaleDateString('es-ES', {
                                        day: '2-digit',
                                        month: '2-digit',
                                        year: 'numeric'
                                    });
                                } catch (e) {
                                    fechaFormateada = pago.fecha; // Mostrar el valor crudo si falla el parseo
                                }

                                return (
                                    <TableRow
                                        key={`${pago.alumnoId}-${pago.id}`}
                                        sx={{ '&:last-child td, &:last-child th': { border: 0 } }}
                                    >
                                        <TableCell component="th" scope="row" sx={{ color: "#ffffff" }}>
                                            {pago.alumno}
                                        </TableCell>
                                        <TableCell align="right" sx={{ color: "#03dac6" }}>${pago.monto.toFixed(2)}</TableCell>
                                        <TableCell sx={{ color: "#ffffff" }}>{fechaFormateada}</TableCell>
                                        <TableCell sx={{ color: "#ffffff" }}>{pago.descripcion}</TableCell>
                                    </TableRow>
                                );
                            })}
                        </TableBody>
                    </Table>
                </TableContainer>
            )}

            <Box sx={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                flexWrap: 'wrap',
                mt: 1,
                padding: 2,
                backgroundColor: "#1e1e1e",
                borderRadius: 2
            }}>
                <Box sx={{ display: 'flex', justifyContent: 'center', padding: 1 }}>
                    <Typography sx={{ textAlign: "center", padding: 2, color: "#bb86fc" }}>
                        Total de Ventas del Mes:
                        <Typography fontSize='1.2rem' color="#03dac6"> ${totalVentasMes.toFixed(2)}</Typography>
                    </Typography>
                </Box>

                <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                    <Typography sx={{ textAlign: "center", padding: 1, color: "#bb86fc" }}>
                        Total de Pagos de Alumnos:
                        <Typography fontSize='1.2rem' color="#03dac6"> ${totalGananciasAlumnos.toFixed(2)}</Typography>
                    </Typography>
                </Box>
            </Box>

            <Box sx={{
                display: 'flex',
                justifyContent: 'center',
                backgroundColor: "#1e1e1e",
                borderRadius: 2,
                padding: 2,
                mt: 2
            }}>
                <Typography fontWeight="bold" sx={{ textAlign: "center", padding: 1, color: "#bb86fc" }}>
                    Ganancia Total:
                    <Typography color="#ff7597" fontSize='1.2rem'> ${(totalVentasMes + totalGananciasAlumnos).toFixed(2)}</Typography>
                </Typography>
            </Box>

            {/* Historial de Ganancias */}
            <Accordion
                expanded={showHistorial}
                onChange={() => setShowHistorial(!showHistorial)}
                sx={{
                    mt: 3,
                    backgroundColor: "#1e1e1e",
                    color: "#ffffff"
                }}
            >
                <AccordionSummary
                    expandIcon={showHistorial ? <ExpandLessIcon style={{ color: "#bb86fc" }} /> : <ExpandMoreIcon style={{ color: "#bb86fc" }} />}
                    sx={{ backgroundColor: '#3700b3' }}
                >
                    <Typography variant="h6" sx={{ fontWeight: 'bold', color: "#ffffff" }}>
                        Historial de Ganancias por Mes
                    </Typography>
                </AccordionSummary>
                <AccordionDetails>
                    <TableContainer component={Paper} sx={{ backgroundColor: "#1e1e1e" }}>
                        <Table>
                            <TableHead>
                                <TableRow sx={{ backgroundColor: '#6200ee' }}>
                                    <TableCell sx={{ fontWeight: 'bold', color: "#ffffff" }}>Mes/Año</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold', color: "#ffffff" }}>Ventas ($)</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold', color: "#ffffff" }}>Clases ($)</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold', color: "#ffffff" }}>Total ($)</TableCell>
                                    <TableCell sx={{ fontWeight: 'bold', color: "#ffffff" }}>Detalles Clases</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {historialGanancias.map((item, index) => (
                                    <TableRow key={index} sx={{ '&:last-child td, &:last-child th': { border: 0 } }}>
                                        <TableCell component="th" scope="row" sx={{ color: "#ffffff" }}>
                                            {obtenerNombreMes(item.mes)} {item.anio}
                                        </TableCell>
                                        <TableCell align="right" sx={{ color: "#03dac6" }}>{item.totalVentas.toFixed(2)}</TableCell>
                                        <TableCell align="right" sx={{ color: "#03dac6" }}>{item.totalClases.toFixed(2)}</TableCell>
                                        <TableCell align="right" sx={{ fontWeight: 'bold', color: "#ff7597" }}>
                                            {(item.totalVentas + item.totalClases).toFixed(2)}
                                        </TableCell>
                                        <TableCell>
                                            <Accordion sx={{ backgroundColor: "#1e1e1e" }}>
                                                <AccordionSummary expandIcon={<ExpandMoreIcon style={{ color: "#bb86fc" }} />}>
                                                    <Typography variant="body2" style={{ color: "#ffffff" }}>Ver detalles</Typography>
                                                </AccordionSummary>
                                                <AccordionDetails>
                                                    {item.detallesClases && item.detallesClases.length > 0 ? (
                                                        <Table size="small" sx={{ backgroundColor: "#1e1e1e" }}>
                                                            <TableHead>
                                                                <TableRow sx={{ backgroundColor: '#6200ee' }}>
                                                                    <TableCell sx={{ color: "#ffffff" }}>Alumno</TableCell>
                                                                    <TableCell sx={{ color: "#ffffff" }}>Descripción</TableCell>
                                                                    <TableCell align="right" sx={{ color: "#ffffff" }}>Monto</TableCell>
                                                                    <TableCell sx={{ color: "#ffffff" }}>Fecha</TableCell>
                                                                </TableRow>
                                                            </TableHead>
                                                            <TableBody>
                                                                {item.detallesClases.map((clase, idx) => (
                                                                    <TableRow key={idx}>
                                                                        <TableCell sx={{ color: "#ffffff" }}>{clase.alumno}</TableCell>
                                                                        <TableCell sx={{ color: "#ffffff" }}>{clase.descripcion}</TableCell>
                                                                        <TableCell align="right" sx={{ color: "#03dac6" }}>{clase.monto.toFixed(2)}</TableCell>
                                                                        <TableCell sx={{ color: "#ffffff" }}>{new Date(clase.fecha).toLocaleDateString()}</TableCell>
                                                                    </TableRow>
                                                                ))}
                                                            </TableBody>
                                                        </Table>
                                                    ) : (
                                                        <Typography variant="body2" style={{ color: "#ffffff" }}>No hay detalles disponibles</Typography>
                                                    )}
                                                </AccordionDetails>
                                            </Accordion>
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </AccordionDetails>
            </Accordion>

            <Box sx={{ display: 'flex', justifyContent: 'right', mt: 4 }}>
                <Button
                    variant="contained"
                    sx={{
                        borderRadius: 7,
                        backgroundColor: "#ff7597",
                        color: "white",
                        display: 'flex',
                        justifyContent: 'right',
                        '&:hover': { backgroundColor: "#ff4081" }
                    }}
                    onClick={() => navigate(-1)}
                >
                    Volver
                </Button>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'end', mt: 3 }}>
                <Typography fontSize='0.7rem' style={{ color: "#bb86fc" }}>Powered By PaBLo A.</Typography>
            </Box>
        </Box>
    );
};

export default VentaVarios;