import React, { createContext, useContext, useState, useMemo } from 'react';
import { createTheme } from '@mui/material/styles';

const ThemeContext = createContext();

export const useThemeContext = () => {
    const context = useContext(ThemeContext);
    if (!context) {
        throw new Error('useThemeContext must be used within ThemeProvider');
    }
    return context;
};

export const ThemeContextProvider = ({ children }) => {
    // Forzar modo claro siempre
    const actualTheme = 'light';

    // Tema claro con colores violáceos, naranjas y azules
    const theme = useMemo(() => createTheme({
        palette: {
            mode: 'light',
            primary: {
                main: '#7c3aed',     // Violeta principal
                light: '#a78bfa',    // Violeta claro
                dark: '#5b21b6',     // Violeta oscuro
            },
            secondary: {
                main: '#ea580c',     // Naranja principal
                light: '#f97316',    // Naranja claro
                dark: '#c2410c',     // Naranja oscuro
            },
            accent: {
                main: '#3b82f6',     // Azul principal
                light: '#60a5fa',    // Azul claro
                dark: '#2563eb',     // Azul oscuro
            },
            background: {
                default: '#f8fafc',  // Fondo gris muy claro
                paper: '#ffffff',    // Blanco para tarjetas
            },
            text: {
                primary: '#1e293b',  // Texto principal oscuro
                secondary: '#64748b', // Texto secundario gris
            },
        },
        components: {
            MuiButton: {
                styleOverrides: {
                    root: {
                        borderRadius: '40px',
                        textTransform: 'none',
                        fontWeight: 600,
                    },
                },
            },
            MuiCard: {
                styleOverrides: {
                    root: {
                        borderRadius: '16px',
                        transition: 'all 0.3s ease',
                        '&:hover': {
                            transform: 'translateY(-2px)',
                            boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)',
                        },
                    },
                },
            },
            MuiPaper: {
                styleOverrides: {
                    root: {
                        backgroundImage: 'none',
                    },
                },
            },
        },
    }), []);

    const value = {
        actualTheme,
        theme,
    };

    return (
        <ThemeContext.Provider value={value}>
            {children}
        </ThemeContext.Provider>
    );
};